Effect Down
{
	VertexShader = "VertexShader"
	PixelShader = "PixelShaderDown"
}

Effect Disable
{
	VertexShader = "VertexShader"
	PixelShader = "PixelShaderDisable"
}

Effect Over
{
	VertexShader = "VertexShader"
	PixelShader = "PixelShaderOver"
}

Includes = {
}

PixelShader =
{
	Samplers =
	{
		MapTexture =
		{
			Index = 0
			MagFilter = "Point"
			MinFilter = "Linear"
			MipFilter = "None"
			AddressU = "Clamp"
			AddressV = "Clamp"
		}
	}
}


VertexStruct VS_INPUT
{
	float3 vPosition  : POSITION;
	float2 vTexCoord  : TEXCOORD0;
};

VertexStruct VS_OUTPUT
{
	float4  vPosition : PDX_POSITION;
	float2  vTexCoord : TEXCOORD0;
	float2  vHdUI : TEXCOORD3;
};


ConstantBuffer( 0, 0 )
{
	float4x4 WorldViewProjectionMatrix;	
	float4 Color;
	float vXOffset;	// For textures with more than one frame
};


VertexShader =
{
	MainCode VertexShader
	[[
		
		VS_OUTPUT main(const VS_INPUT v )
		{
		    VS_OUTPUT Out;
		    Out.vPosition  = mul( WorldViewProjectionMatrix, float4( v.vPosition.xyz, 1 ) );
			Out.vHdUI = v.vPosition.xy;
		
		    Out.vTexCoord  = v.vTexCoord;
			Out.vTexCoord.x += vXOffset;
		    return Out;
		}
		
		
	]]
}

PixelShader =
{
	MainCode PixelShaderUp
	[[
			
		float4 main( VS_OUTPUT v ) : PDX_COLOR
		{
		    float2 vHdUV = v.vTexCoord;
#ifdef PDX_DIRECTX_9
			// At UI scale 2 the DX9 GUI is half a screen pixel off D3D9's texel/pixel alignment, so 1:1
			// glyphs get averaged with their neighbours and 2x magnified art comes out unevenly jagged.
			// Shift sampling back onto texel centres.
			vHdUV += 0.5 * float2( ddx( vHdUV ).x, ddy( vHdUV ).y );
#endif
			float4 OutColor = tex2D( MapTexture, vHdUV );
			// UI art, and on DX9 the render targets, is magnified 2x: sharpen it.
			float2 vHdDX = float2( ddx( vHdUV ).x, 0.0 );
			float2 vHdDY = float2( 0.0, ddy( vHdUV ).y );
			float4 vHdN = tex2D( MapTexture, vHdUV - vHdDY );
			float4 vHdS = tex2D( MapTexture, vHdUV + vHdDY );
			float4 vHdW = tex2D( MapTexture, vHdUV - vHdDX );
			float4 vHdE = tex2D( MapTexture, vHdUV + vHdDX );
			float3 vHdB = vHdN.rgb * vHdN.a;
			float3 vHdH = vHdS.rgb * vHdS.a;
			float3 vHdD = vHdW.rgb * vHdW.a;
			float3 vHdF = vHdE.rgb * vHdE.a;
			float3 vHdC = OutColor.rgb * OutColor.a;
			float3 vHdMin = min( min( vHdB, vHdD ), min( vHdF, vHdH ) );
			float3 vHdMax = max( max( vHdB, vHdD ), max( vHdF, vHdH ) );
			float3 vHdLobe3 = max( -vHdMin / ( 4.0 * vHdMax + 0.0001 ), ( 1.0 - vHdMax ) / ( 4.0 * vHdMin - 4.0001 ) );
			float vHdLobe = max( -0.1875, min( max( vHdLobe3.r, max( vHdLobe3.g, vHdLobe3.b ) ), 0.0 ) );
			float3 vHdSharp = saturate( ( vHdLobe * ( vHdB + vHdD + vHdF + vHdH ) + vHdC ) / ( 4.0 * vHdLobe + 1.0 ) );
			vHdSharp = saturate( vHdSharp / max( OutColor.a, 1.0 / 255.0 ) );
			float3 vHdRGB = vHdSharp;
			// Texel size from the texture's UV change per UI unit, snapped to a whole number of texels so the
			// samples below hit texel centres exactly.
			float2 vHdUnit = abs( float2( ddx( vHdUV ).x, ddy( vHdUV ).y ) ) / max( abs( float2( ddx( v.vHdUI.x ), ddy( v.vHdUI.y ) ) ), 0.00001 );
			vHdUnit = 1.0 / max( floor( 1.0 / vHdUnit + 0.5 ), 1.0 );
			if ( all( abs( tex2Dlod0( MapTexture, 0.5 * vHdUnit ) - ( float4( 90.0, 60.0, 165.0, 255.0 ) / 255.0 ) ) < 0.5 / 255.0 ) )
			{
				float2 vHdPos = vHdUV / vHdUnit;
				float2 vHdCell = floor( vHdPos );
				float2 vHdSub = step( 0.5, vHdPos - vHdCell );
				float4 vHdTmm = tex2Dlod0( MapTexture, ( vHdCell + float2( -0.5, -0.5 ) ) * vHdUnit );
				float fHdPmm = max( step( 254.5 / 255.0, vHdTmm.a ), vHdCell.x == 1.0 && abs( vHdCell.y + -1.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTzm = tex2Dlod0( MapTexture, ( vHdCell + float2( 0.5, -0.5 ) ) * vHdUnit );
				float fHdPzm = max( step( 254.5 / 255.0, vHdTzm.a ), vHdCell.x == 0.0 && abs( vHdCell.y + -1.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTpm = tex2Dlod0( MapTexture, ( vHdCell + float2( 1.5, -0.5 ) ) * vHdUnit );
				float fHdPpm = max( step( 254.5 / 255.0, vHdTpm.a ), vHdCell.x == -1.0 && abs( vHdCell.y + -1.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTmz = tex2Dlod0( MapTexture, ( vHdCell + float2( -0.5, 0.5 ) ) * vHdUnit );
				float fHdPmz = max( step( 254.5 / 255.0, vHdTmz.a ), vHdCell.x == 1.0 && abs( vHdCell.y + -0.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTzz = tex2Dlod0( MapTexture, ( vHdCell + float2( 0.5, 0.5 ) ) * vHdUnit );
				float fHdPzz = max( step( 254.5 / 255.0, vHdTzz.a ), vHdCell.x == 0.0 && abs( vHdCell.y + -0.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTpz = tex2Dlod0( MapTexture, ( vHdCell + float2( 1.5, 0.5 ) ) * vHdUnit );
				float fHdPpz = max( step( 254.5 / 255.0, vHdTpz.a ), vHdCell.x == -1.0 && abs( vHdCell.y + -0.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTmp = tex2Dlod0( MapTexture, ( vHdCell + float2( -0.5, 1.5 ) ) * vHdUnit );
				float fHdPmp = max( step( 254.5 / 255.0, vHdTmp.a ), vHdCell.x == 1.0 && abs( vHdCell.y + 0.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTzp = tex2Dlod0( MapTexture, ( vHdCell + float2( 0.5, 1.5 ) ) * vHdUnit );
				float fHdPzp = max( step( 254.5 / 255.0, vHdTzp.a ), vHdCell.x == 0.0 && abs( vHdCell.y + 0.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTpp = tex2Dlod0( MapTexture, ( vHdCell + float2( 1.5, 1.5 ) ) * vHdUnit );
				float fHdPpp = max( step( 254.5 / 255.0, vHdTpp.a ), vHdCell.x == -1.0 && abs( vHdCell.y + 0.5 ) < 1.0 ? 1.0 : 0.0 );
				float fHdText = fHdPzz + fHdPmm + fHdPzm + fHdPpm + fHdPmz + fHdPpz + fHdPmp + fHdPzp + fHdPpp;
				// The marker texels show their right-hand neighbour.
				float fHdCorner = vHdCell.x == 0.0 && abs( vHdCell.y - 0.5 ) < 1.0 ? 1.0 : 0.0;
				vHdTzz = lerp( vHdTzz, vHdTpz, fHdCorner );
				fHdPzz = lerp( fHdPzz, fHdPpz, fHdCorner );
				if ( fHdPzz > 0.5 )
				{
					float fHdBgN = 8.0 - ( fHdPmm + fHdPzm + fHdPpm + fHdPmz + fHdPpz + fHdPmp + fHdPzp + fHdPpp );
					float4 vHdBg = fHdBgN > 0.5 ? ( ( 1.0 - fHdPmm ) * vHdTmm + ( 1.0 - fHdPzm ) * vHdTzm + ( 1.0 - fHdPpm ) * vHdTpm + ( 1.0 - fHdPmz ) * vHdTmz + ( 1.0 - fHdPpz ) * vHdTpz + ( 1.0 - fHdPmp ) * vHdTmp + ( 1.0 - fHdPzp ) * vHdTzp + ( 1.0 - fHdPpp ) * vHdTpp ) / fHdBgN : tex2Dlod0( MapTexture, float2( 0.5, 1.5 ) * vHdUnit );
					float3 vHdByte = floor( vHdTzz.rgb * 255.0 + 0.5 );
					float3 vHdHi = floor( vHdByte / 16.0 );
					float3 vHdLo = vHdByte - 16.0 * vHdHi;
					float3 vHdQ = floor( vHdLo / 2.0 );
					float4 vHdCov = float4( vHdQ, dot( vHdLo - 2.0 * vHdQ, float3( 1.0, 2.0, 4.0 ) ) ) / 7.0;
					float2 vHdRow = lerp( vHdCov.xz, vHdCov.yw, vHdSub.x );
					float fHdCov = lerp( vHdRow.x, vHdRow.y, vHdSub.y );
					vHdRGB = lerp( vHdBg.rgb, vHdHi / 15.0, fHdCov );
					OutColor.a = lerp( vHdBg.a, 1.0, fHdCov );
				}
				else if ( fHdText > 0.5 )
				{
					float2 vHdW = abs( vHdPos - vHdCell - 0.5 );
					bool bHdR = vHdSub.x > 0.5;
					bool bHdD = vHdSub.y > 0.5;
					float4 vHdX = lerp( bHdR ? vHdTpz : vHdTmz, vHdTzz, bHdR ? fHdPpz : fHdPmz );
					float4 vHdY = lerp( bHdD ? vHdTzp : vHdTzm, vHdTzz, bHdD ? fHdPzp : fHdPzm );
					float4 vHdXY = bHdR ? ( bHdD ? vHdTpp : vHdTpm ) : ( bHdD ? vHdTmp : vHdTmm );
					vHdXY = lerp( vHdXY, vHdTzz, bHdR ? ( bHdD ? fHdPpp : fHdPpm ) : ( bHdD ? fHdPmp : fHdPmm ) );
					float4 vHdLin = lerp( lerp( vHdTzz, vHdX, vHdW.x ), lerp( vHdY, vHdXY, vHdW.x ), vHdW.y );
					vHdRGB = vHdLin.rgb;
					OutColor.a = vHdLin.a;
				}
			}
			OutColor.rgb = vHdRGB;
			OutColor *= Color;
			return OutColor;
		}
		
			
		
	]]

	MainCode PixelShaderDown
	[[
			
		float4 main( VS_OUTPUT v ) : PDX_COLOR
		{
			float2 vHdUV = v.vTexCoord;
#ifdef PDX_DIRECTX_9
			// At UI scale 2 the DX9 GUI is half a screen pixel off D3D9's texel/pixel alignment, so 1:1
			// glyphs get averaged with their neighbours and 2x magnified art comes out unevenly jagged.
			// Shift sampling back onto texel centres.
			vHdUV += 0.5 * float2( ddx( vHdUV ).x, ddy( vHdUV ).y );
#endif
			float4 OutColor = tex2D( MapTexture, vHdUV );
			// UI art, and on DX9 the render targets, is magnified 2x: sharpen it.
			float2 vHdDX = float2( ddx( vHdUV ).x, 0.0 );
			float2 vHdDY = float2( 0.0, ddy( vHdUV ).y );
			float4 vHdN = tex2D( MapTexture, vHdUV - vHdDY );
			float4 vHdS = tex2D( MapTexture, vHdUV + vHdDY );
			float4 vHdW = tex2D( MapTexture, vHdUV - vHdDX );
			float4 vHdE = tex2D( MapTexture, vHdUV + vHdDX );
			float3 vHdB = vHdN.rgb * vHdN.a;
			float3 vHdH = vHdS.rgb * vHdS.a;
			float3 vHdD = vHdW.rgb * vHdW.a;
			float3 vHdF = vHdE.rgb * vHdE.a;
			float3 vHdC = OutColor.rgb * OutColor.a;
			float3 vHdMin = min( min( vHdB, vHdD ), min( vHdF, vHdH ) );
			float3 vHdMax = max( max( vHdB, vHdD ), max( vHdF, vHdH ) );
			float3 vHdLobe3 = max( -vHdMin / ( 4.0 * vHdMax + 0.0001 ), ( 1.0 - vHdMax ) / ( 4.0 * vHdMin - 4.0001 ) );
			float vHdLobe = max( -0.1875, min( max( vHdLobe3.r, max( vHdLobe3.g, vHdLobe3.b ) ), 0.0 ) );
			float3 vHdSharp = saturate( ( vHdLobe * ( vHdB + vHdD + vHdF + vHdH ) + vHdC ) / ( 4.0 * vHdLobe + 1.0 ) );
			vHdSharp = saturate( vHdSharp / max( OutColor.a, 1.0 / 255.0 ) );
			float3 vHdRGB = vHdSharp;
			// Texel size from the texture's UV change per UI unit, snapped to a whole number of texels so the
			// samples below hit texel centres exactly.
			float2 vHdUnit = abs( float2( ddx( vHdUV ).x, ddy( vHdUV ).y ) ) / max( abs( float2( ddx( v.vHdUI.x ), ddy( v.vHdUI.y ) ) ), 0.00001 );
			vHdUnit = 1.0 / max( floor( 1.0 / vHdUnit + 0.5 ), 1.0 );
			if ( all( abs( tex2Dlod0( MapTexture, 0.5 * vHdUnit ) - ( float4( 90.0, 60.0, 165.0, 255.0 ) / 255.0 ) ) < 0.5 / 255.0 ) )
			{
				float2 vHdPos = vHdUV / vHdUnit;
				float2 vHdCell = floor( vHdPos );
				float2 vHdSub = step( 0.5, vHdPos - vHdCell );
				float4 vHdTmm = tex2Dlod0( MapTexture, ( vHdCell + float2( -0.5, -0.5 ) ) * vHdUnit );
				float fHdPmm = max( step( 254.5 / 255.0, vHdTmm.a ), vHdCell.x == 1.0 && abs( vHdCell.y + -1.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTzm = tex2Dlod0( MapTexture, ( vHdCell + float2( 0.5, -0.5 ) ) * vHdUnit );
				float fHdPzm = max( step( 254.5 / 255.0, vHdTzm.a ), vHdCell.x == 0.0 && abs( vHdCell.y + -1.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTpm = tex2Dlod0( MapTexture, ( vHdCell + float2( 1.5, -0.5 ) ) * vHdUnit );
				float fHdPpm = max( step( 254.5 / 255.0, vHdTpm.a ), vHdCell.x == -1.0 && abs( vHdCell.y + -1.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTmz = tex2Dlod0( MapTexture, ( vHdCell + float2( -0.5, 0.5 ) ) * vHdUnit );
				float fHdPmz = max( step( 254.5 / 255.0, vHdTmz.a ), vHdCell.x == 1.0 && abs( vHdCell.y + -0.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTzz = tex2Dlod0( MapTexture, ( vHdCell + float2( 0.5, 0.5 ) ) * vHdUnit );
				float fHdPzz = max( step( 254.5 / 255.0, vHdTzz.a ), vHdCell.x == 0.0 && abs( vHdCell.y + -0.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTpz = tex2Dlod0( MapTexture, ( vHdCell + float2( 1.5, 0.5 ) ) * vHdUnit );
				float fHdPpz = max( step( 254.5 / 255.0, vHdTpz.a ), vHdCell.x == -1.0 && abs( vHdCell.y + -0.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTmp = tex2Dlod0( MapTexture, ( vHdCell + float2( -0.5, 1.5 ) ) * vHdUnit );
				float fHdPmp = max( step( 254.5 / 255.0, vHdTmp.a ), vHdCell.x == 1.0 && abs( vHdCell.y + 0.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTzp = tex2Dlod0( MapTexture, ( vHdCell + float2( 0.5, 1.5 ) ) * vHdUnit );
				float fHdPzp = max( step( 254.5 / 255.0, vHdTzp.a ), vHdCell.x == 0.0 && abs( vHdCell.y + 0.5 ) < 1.0 ? 1.0 : 0.0 );
				float4 vHdTpp = tex2Dlod0( MapTexture, ( vHdCell + float2( 1.5, 1.5 ) ) * vHdUnit );
				float fHdPpp = max( step( 254.5 / 255.0, vHdTpp.a ), vHdCell.x == -1.0 && abs( vHdCell.y + 0.5 ) < 1.0 ? 1.0 : 0.0 );
				float fHdText = fHdPzz + fHdPmm + fHdPzm + fHdPpm + fHdPmz + fHdPpz + fHdPmp + fHdPzp + fHdPpp;
				// The marker texels show their right-hand neighbour.
				float fHdCorner = vHdCell.x == 0.0 && abs( vHdCell.y - 0.5 ) < 1.0 ? 1.0 : 0.0;
				vHdTzz = lerp( vHdTzz, vHdTpz, fHdCorner );
				fHdPzz = lerp( fHdPzz, fHdPpz, fHdCorner );
				if ( fHdPzz > 0.5 )
				{
					float fHdBgN = 8.0 - ( fHdPmm + fHdPzm + fHdPpm + fHdPmz + fHdPpz + fHdPmp + fHdPzp + fHdPpp );
					float4 vHdBg = fHdBgN > 0.5 ? ( ( 1.0 - fHdPmm ) * vHdTmm + ( 1.0 - fHdPzm ) * vHdTzm + ( 1.0 - fHdPpm ) * vHdTpm + ( 1.0 - fHdPmz ) * vHdTmz + ( 1.0 - fHdPpz ) * vHdTpz + ( 1.0 - fHdPmp ) * vHdTmp + ( 1.0 - fHdPzp ) * vHdTzp + ( 1.0 - fHdPpp ) * vHdTpp ) / fHdBgN : tex2Dlod0( MapTexture, float2( 0.5, 1.5 ) * vHdUnit );
					float3 vHdByte = floor( vHdTzz.rgb * 255.0 + 0.5 );
					float3 vHdHi = floor( vHdByte / 16.0 );
					float3 vHdLo = vHdByte - 16.0 * vHdHi;
					float3 vHdQ = floor( vHdLo / 2.0 );
					float4 vHdCov = float4( vHdQ, dot( vHdLo - 2.0 * vHdQ, float3( 1.0, 2.0, 4.0 ) ) ) / 7.0;
					float2 vHdRow = lerp( vHdCov.xz, vHdCov.yw, vHdSub.x );
					float fHdCov = lerp( vHdRow.x, vHdRow.y, vHdSub.y );
					vHdRGB = lerp( vHdBg.rgb, vHdHi / 15.0, fHdCov );
					OutColor.a = lerp( vHdBg.a, 1.0, fHdCov );
				}
				else if ( fHdText > 0.5 )
				{
					float2 vHdW = abs( vHdPos - vHdCell - 0.5 );
					bool bHdR = vHdSub.x > 0.5;
					bool bHdD = vHdSub.y > 0.5;
					float4 vHdX = lerp( bHdR ? vHdTpz : vHdTmz, vHdTzz, bHdR ? fHdPpz : fHdPmz );
					float4 vHdY = lerp( bHdD ? vHdTzp : vHdTzm, vHdTzz, bHdD ? fHdPzp : fHdPzm );
					float4 vHdXY = bHdR ? ( bHdD ? vHdTpp : vHdTpm ) : ( bHdD ? vHdTmp : vHdTmm );
					vHdXY = lerp( vHdXY, vHdTzz, bHdR ? ( bHdD ? fHdPpp : fHdPpm ) : ( bHdD ? fHdPmp : fHdPmm ) );
					float4 vHdLin = lerp( lerp( vHdTzz, vHdX, vHdW.x ), lerp( vHdY, vHdXY, vHdW.x ), vHdW.y );
					vHdRGB = vHdLin.rgb;
					OutColor.a = vHdLin.a;
				}
			}
			OutColor.rgb = vHdRGB;
			float4 MixColor = float4( 0.1, 0.1, 0.1, 0 );
			OutColor -= MixColor;
			OutColor *= Color;
			return OutColor;
		}
		
			
		
	]]

